* { box-sizing: border-box; }
:root {
  color-scheme: dark;
  font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  font-size: 16px;
  color: #f4f2e9;
  background: #182d3a;
  --ink: #f4f2e9;
  --muted: #a9bac0;
  --mint: #91e6bd;
  --gold: #f2c66d;
  --panel: #243e4c;
}
body {
  min-height: 100vh;
  margin: 0;
  padding: 32px 16px;
  display: grid;
  place-items: center;
  background-color: #182d3a;
  background-image: linear-gradient(30deg, #203744 12%, transparent 12.5%, transparent 87%, #203744 87.5%), linear-gradient(150deg, #203744 12%, transparent 12.5%, transparent 87%, #203744 87.5%), linear-gradient(30deg, #203744 12%, transparent 12.5%, transparent 87%, #203744 87.5%), linear-gradient(150deg, #203744 12%, transparent 12.5%, transparent 87%, #203744 87.5%);
  background-size: 48px 84px;
  background-position: 0 0, 0 0, 24px 42px, 24px 42px;
}
.counter {
  width: min(100%, 520px);
  padding: clamp(24px, 7vw, 44px);
  border: 2px solid #45616a;
  border-radius: 18px;
  background: #1d3542;
  box-shadow: 0 14px 0 #10232d, 0 24px 50px #0c1c2480;
}
.header { text-align: center; }
.eyebrow { margin: 0 0 8px; color: var(--mint); font-size: .8rem; font-weight: 800; letter-spacing: .18em; }
h1 { margin: 0; font-size: clamp(1.5rem, 6vw, 2rem); line-height: 1.2; }
.current-ticket {
  width: 144px;
  height: 112px;
  margin: 24px auto 8px;
  display: grid;
  place-items: center;
  border: 3px solid var(--gold);
  border-radius: 12px;
  background: #132832;
  box-shadow: inset 0 0 0 5px #132832, inset 0 0 0 7px #48606a;
  color: var(--gold);
  font-size: 3.5rem;
  font-weight: 850;
  font-variant-numeric: tabular-nums;
}
.current-caption { margin: 0; color: var(--muted); }
.actions { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; margin-top: 28px; }
.button {
  min-height: 54px;
  padding: 12px 14px;
  border: 2px solid transparent;
  border-radius: 9px;
  font: inherit;
  font-weight: 750;
  cursor: pointer;
  transition: transform .12s ease, filter .12s ease, box-shadow .12s ease;
}
.button-primary { color: #152d36; background: var(--mint); box-shadow: 0 4px 0 #4c9e7d; }
.button-secondary { color: #30280f; background: var(--gold); box-shadow: 0 4px 0 #aa8140; }
.button:hover { filter: brightness(1.08); transform: translateY(-2px); }
.button:active { transform: translateY(2px); box-shadow: none; }
.button:focus-visible { outline: 3px solid var(--ink); outline-offset: 4px; }
.status { min-height: 24px; margin: 22px 0 18px; color: var(--muted); text-align: center; }
.queue { padding: 18px; border: 1px solid #45616a; border-radius: 12px; background: var(--panel); }
.queue-heading { display: flex; align-items: center; justify-content: space-between; gap: 12px; }
h2 { margin: 0; font-size: 1.1rem; }
.count { padding: 5px 10px; border-radius: 999px; color: #17343a; background: var(--mint); font-size: .9rem; font-weight: 750; white-space: nowrap; }
.waiting-list { display: flex; flex-wrap: wrap; gap: 8px; min-height: 40px; margin: 16px 0 0; padding: 0; list-style: none; }
.waiting-list li { min-width: 42px; padding: 8px 12px; border: 1px solid #6d8790; border-radius: 7px; background: #1b303a; text-align: center; font-weight: 750; font-variant-numeric: tabular-nums; }
.waiting-list .empty-state { width: 100%; padding: 8px 0; border: 0; background: transparent; color: var(--muted); text-align: left; font-weight: 400; }
footer { margin-top: 22px; color: var(--muted); text-align: center; font-size: .9rem; }
@media (max-width: 420px) {
  body { padding: 20px 12px; }
  .actions { grid-template-columns: 1fr; }
}

const waiting = [];
let nextTicket = 1;
let currentTicket = null;

const currentNumber = document.querySelector("#currentNumber");
const waitingCount = document.querySelector("#waitingCount");
const waitingList = document.querySelector("#waitingList");
const status = document.querySelector("#status");

function render() {
  currentNumber.textContent = currentTicket ?? "—";
  waitingCount.textContent = waiting.length;
  waitingList.replaceChildren();
  if (waiting.length === 0) {
    const empty = document.createElement("li");
    empty.className = "empty-state";
    empty.textContent = "No tickets waiting yet.";
    waitingList.append(empty);
    return;
  }
  for (const ticket of waiting) {
    const item = document.createElement("li");
    item.textContent = ticket;
    waitingList.append(item);
  }
}

document.querySelector("#takeButton").addEventListener("click", () => {
  const ticket = nextTicket++;
  waiting.push(ticket);
  status.textContent = `Ticket ${ticket} added to the waiting room.`;
  render();
});

document.querySelector("#serveButton").addEventListener("click", () => {
  if (waiting.length === 0) {
    status.textContent = "No tickets are waiting to be served.";
    return;
  }
  currentTicket = waiting.shift();
  status.textContent = `Now serving ticket ${currentTicket}.`;
  render();
});

render();
